import{_ as e,C as o,c as a,o as t,a0 as s,b as i,w as n,a as l,G as r,a1 as d}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Establecimiento de objetivos para los jugadores de petanca","description":"","frontmatter":{},"headers":[],"relativePath":"es/education/goals/index.md","filePath":"es/education/goals/index.md"}');const u=e({name:"es/education/goals/index.md"},[["render",function(e,c,u,p,m,b){const g=o("Mermaid");return t(),a("div",null,[c[1]||(c[1]=s('<h1 id="establecimiento-de-objetivos-para-los-jugadores-de-petanca" tabindex="-1">Establecimiento de objetivos para los jugadores de petanca <a class="header-anchor" href="#establecimiento-de-objetivos-para-los-jugadores-de-petanca" aria-label="Permalink to &quot;Establecimiento de objetivos para los jugadores de petanca&quot;">​</a></h1><p>Las metas claras son tu brújula. Te guían en tu entrenamiento, te motivan cuando las cosas se ponen difíciles y te permiten medir tu progreso. Sin metas, solo estás jugando. Con metas, avanzas hacia algo.</p><div class="tip custom-block"><p class="custom-block-title">El principio fundamental</p><p><strong>Una meta sin un plan es solo un deseo.</strong> Establece metas claras, divídelas en partes, concéntrate en lo que controlas y realiza un seguimiento de tu progreso.</p></div><h2 id="por-que-son-importantes-los-objetivos" tabindex="-1">Por qué son importantes los objetivos <a class="header-anchor" href="#por-que-son-importantes-los-objetivos" aria-label="Permalink to &quot;Por qué son importantes los objetivos&quot;">​</a></h2><p>Los objetivos sirven para múltiples propósitos:</p><ul><li><strong>Dirección:</strong> Saber en qué trabajar</li><li><strong>Motivación:</strong> Tener algo por lo que luchar</li><li><strong>Medición:</strong> Sigue tu progreso</li><li><strong>Enfoque:</strong> Prioriza tu tiempo limitado</li></ul><p>Para el jugador autodidacta, las metas son especialmente importantes. Sin un entrenador que te presione, tus metas se convierten en tu guía.</p><h2 id="los-tres-tipos-de-objetivos" tabindex="-1">Los tres tipos de objetivos <a class="header-anchor" href="#los-tres-tipos-de-objetivos" aria-label="Permalink to &quot;Los tres tipos de objetivos&quot;">​</a></h2><p>No todos los objetivos son iguales. Comprender los diferentes tipos te ayudará a establecer objetivos más acertados.</p><h3 id="_1-objetivos-de-resultados" tabindex="-1">1. Objetivos de resultados <a class="header-anchor" href="#_1-objetivos-de-resultados" aria-label="Permalink to &quot;1. Objetivos de resultados&quot;">​</a></h3><p><strong>Qué:</strong> El resultado final que deseas <strong>Ejemplo:</strong> &quot;Ganar el campeonato regional&quot; <strong>Nivel de control:</strong> Bajo - depende de los oponentes, las condiciones y la suerte.</p><h3 id="_2-metas-de-desempeno" tabindex="-1">2. Metas de desempeño <a class="header-anchor" href="#_2-metas-de-desempeno" aria-label="Permalink to &quot;2. Metas de desempeño&quot;">​</a></h3><p><strong>Qué:</strong> Estándares de desempeño específicos <strong>Ejemplo:</strong> &quot;Lograr una precisión del 80% en los ejercicios de tiro&quot; <strong>Nivel de control:</strong> Medio - depende principalmente de usted</p><h3 id="_3-objetivos-del-proceso" tabindex="-1">3. Objetivos del proceso <a class="header-anchor" href="#_3-objetivos-del-proceso" aria-label="Permalink to &quot;3. Objetivos del proceso&quot;">​</a></h3><p><strong>Qué:</strong> Acciones y comportamientos que controlas <strong>Ejemplo:</strong> &quot;Completar mi rutina previa al lanzamiento en cada lanzamiento&quot; <strong>Nivel de control:</strong> Alto - depende totalmente de usted</p><h3 id="la-jerarquia-de-objetivos" tabindex="-1">La jerarquía de objetivos <a class="header-anchor" href="#la-jerarquia-de-objetivos" aria-label="Permalink to &quot;La jerarquía de objetivos&quot;">​</a></h3>',16)),(t(),i(d,null,{default:n(()=>[r(g,{id:"mermaid-69",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BObjetivo%20de%20resultado%20%3Cbr%2F%3E%20El%20sue%C3%B1o%5D%20--%3E%20B%5BMetas%20de%20desempe%C3%B1o%20%3Cbr%2F%3E%20Hitos%5D%0A%20%20%20%20B%20--%3E%20C%5BObjetivos%20del%20proceso%20%3Cbr%2F%3E%20Acciones%20diarias%5D%0A%0A%20%20%20%20A2%5B%26quot%3BGana%20el%20Campeonato%20Regional%26quot%3B%5D%20--%3E%20B2%5B%26quot%3B80%25%20de%20precisi%C3%B3n%20de%20tiro%26quot%3B%5D%0A%20%20%20%20B2%20--%3E%20C2%5B%26quot%3BRutina%20completa%20previa%20al%20disparo%20%3Cbr%2F%3E%20cada%20lanzamiento%26quot%3B%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e1f5ff%0A%20%20%20%20style%20B%20fill%3A%23fff9c4%0A%20%20%20%20style%20C%20fill%3A%23c8e6c9%0A%20%20%20%20style%20A2%20fill%3A%23e1f5ff%0A%20%20%20%20style%20B2%20fill%3A%23fff9c4%0A%20%20%20%20style%20C2%20fill%3A%23c8e6c9%0A"})]),fallback:n(()=>[...c[0]||(c[0]=[l(" Loading... ",-1)])]),_:1})),c[2]||(c[2]=s('<div class="warning custom-block"><p class="custom-block-title">Visión clave</p><p><strong>Concentre la mayor parte de su atención en los objetivos del proceso.</strong> Son lo que usted controla y conducen a los resultados que desea.</p><ul><li><strong>Objetivos de resultado:</strong> Bajo control, alta motivación</li><li><strong>Objetivos de rendimiento:</strong> Control medio, progreso medible</li><li><strong>Objetivos del proceso:</strong> Alto control, enfoque diario ← <strong>Enfoque aquí</strong></li></ul></div><h2 id="el-marco-smart" tabindex="-1">El marco SMART <a class="header-anchor" href="#el-marco-smart" aria-label="Permalink to &quot;El marco SMART&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Lista de verificación de objetivos SMART</p><p>Todo objetivo debe ser:</p><ul><li>✅ <strong>E</strong>specífico - Claro y bien definido</li><li>✅ <strong>M</strong>edible: puedes seguir tu progreso</li><li>✅ <strong>A</strong>lcanzable - Desafiante pero posible</li><li>✅ <strong>R</strong>elevante - Alineado con tu panorama general</li><li>✅ **Límite temporal: tiene una fecha límite</li></ul></div><h3 id="s-especifico" tabindex="-1">S - Específico <a class="header-anchor" href="#s-especifico" aria-label="Permalink to &quot;S - Específico&quot;">​</a></h3><p>❌ &quot;Mejora tus tiros&quot; ✅ &quot;Mejora mi precisión de au fer (impacto directo) desde 8 metros&quot;</p><h3 id="m-medible" tabindex="-1">M - Medible <a class="header-anchor" href="#m-medible" aria-label="Permalink to &quot;M - Medible&quot;">​</a></h3><p>❌ &quot;Dispara con más precisión&quot; ✅ &quot;Obtén al menos 24/30 en el ejercicio de escalera de tiro&quot;</p><h3 id="a-alcanzable" tabindex="-1">A - Alcanzable <a class="header-anchor" href="#a-alcanzable" aria-label="Permalink to &quot;A - Alcanzable&quot;">​</a></h3><p>❌ &quot;Nunca pierdas un tiro&quot; (imposible) ✅ &quot;Mejorar la precisión en un 10% en 8 semanas&quot; (desafiante pero realista)</p><h3 id="r-relevante" tabindex="-1">R - Relevante <a class="header-anchor" href="#r-relevante" aria-label="Permalink to &quot;R - Relevante&quot;">​</a></h3><p>❌ &quot;Correr un maratón&quot; (no está directamente relacionado) ✅ &quot;Mejora el equilibrio y la estabilidad para un mejor lanzamiento&quot; (apoya tu juego)</p><h3 id="t-limitado-en-el-tiempo" tabindex="-1">T - Limitado en el tiempo <a class="header-anchor" href="#t-limitado-en-el-tiempo" aria-label="Permalink to &quot;T - Limitado en el tiempo&quot;">​</a></h3><p>❌ &quot;Algún día seré mejor&quot; ✅ &quot;Para el 15 de marzo lograré...&quot;</p><h2 id="ejemplos-de-objetivos-para-la-petanca" tabindex="-1">Ejemplos de objetivos para la petanca <a class="header-anchor" href="#ejemplos-de-objetivos-para-la-petanca" aria-label="Permalink to &quot;Ejemplos de objetivos para la petanca&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tipo</th><th>Gol pobre</th><th>Objetivo SMART</th></tr></thead><tbody><tr><td>Resultado</td><td>&quot;Gana más&quot;</td><td>&quot;Llegar a las semifinales en el Torneo de Primavera&quot;</td></tr><tr><td>Actuación</td><td>&quot;Apunta mejor&quot;</td><td>Consigue el 70% de los puntos en un radio de 50 cm a una distancia de 8 m.</td></tr><tr><td>Proceso</td><td>&quot;Practica más&quot;</td><td>Completar 3 sesiones de entrenamiento enfocadas por semana.</td></tr></tbody></table><h2 id="desglosando-los-grandes-objetivos" tabindex="-1">Desglosando los grandes objetivos <a class="header-anchor" href="#desglosando-los-grandes-objetivos" aria-label="Permalink to &quot;Desglosando los grandes objetivos&quot;">​</a></h2><p>Las metas grandes pueden resultar abrumadoras. Divídelas en partes más pequeñas:</p><h3 id="ejemplo-quot-ganar-el-campeonato-de-clubes-dentro-de-12-meses-quot" tabindex="-1">Ejemplo: &quot;Ganar el Campeonato de Clubes (dentro de 12 meses)&quot; <a class="header-anchor" href="#ejemplo-quot-ganar-el-campeonato-de-clubes-dentro-de-12-meses-quot" aria-label="Permalink to &quot;Ejemplo: &amp;quot;Ganar el Campeonato de Clubes (dentro de 12 meses)&amp;quot;&quot;">​</a></h3><p><strong>Objetivo anual:</strong> Ganar el campeonato del club</p><p><strong>Objetivos trimestrales:</strong></p><ul><li>T1: Mejorar la precisión de disparo al 75%</li><li>T2: Desarrollar una rutina consistente antes de disparar</li><li>Q3: Domina las situaciones de presión</li><li>T4: Máximo rendimiento y preparación para la competición</li></ul><p><strong>Objetivos mensuales (T1):</strong></p><ul><li>Mes 1: Establecer una línea base, identificar debilidades</li><li>Mes 2: Enfoque en la técnica de tiro</li><li>Mes 3: Añade presión a la práctica de tiro</li></ul><p><strong>Objetivos semanales (Mes 2):</strong></p><ul><li>Semana 1: 3 sesiones de rodaje, análisis de vídeo</li><li>Semana 2: Trabajar en el problema técnico identificado</li><li>Semana 3: Aumenta la distancia gradualmente</li><li>Semana 4: Progreso de la prueba, ajuste el plan</li></ul><h2 id="conectando-tus-metas-con-tu-quot-por-que-quot" tabindex="-1">Conectando tus metas con tu &quot;por qué&quot; <a class="header-anchor" href="#conectando-tus-metas-con-tu-quot-por-que-quot" aria-label="Permalink to &quot;Conectando tus metas con tu &amp;quot;por qué&amp;quot;&quot;">​</a></h2><p>Los objetivos funcionan mejor cuando están conectados a una motivación más profunda.</p><p>Pregúntese:</p><ul><li>¿Por qué quiero lograr esto?</li><li>¿Qué significará para mí?</li><li>¿Cómo me sentiré cuando tenga éxito?</li><li>¿Qué me impulsa a mejorar?</li></ul><p>Anota tus respuestas. Revísalas cuando te falte la motivación.</p><h2 id="en-esta-seccion" tabindex="-1">En esta sección <a class="header-anchor" href="#en-esta-seccion" aria-label="Permalink to &quot;En esta sección&quot;">​</a></h2><ul><li><strong><a href="/es/educacion/objetivos/objetivos-inteligentes">Objetivos SMART en detalle</a></strong> - Profundice en la creación de objetivos efectivos</li><li><strong><a href="/es/educacion/objetivos/planificación">Creando tu plan de entrenamiento</a></strong> - Convierte tus objetivos en acción</li></ul><h2 id="resumen-reglas-para-establecer-objetivos" tabindex="-1">Resumen: Reglas para establecer objetivos <a class="header-anchor" href="#resumen-reglas-para-establecer-objetivos" aria-label="Permalink to &quot;Resumen: Reglas para establecer objetivos&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Regla n.° 1: La regla del control</p><p><strong>Concéntrese en los objetivos del proceso (lo que usted controla) en lugar de en los objetivos de resultados.</strong> Los objetivos de proceso conducen a objetivos de desempeño, que conducen a objetivos de resultados.</p></div><div class="tip custom-block"><p class="custom-block-title">Regla n.° 2: La regla SMART</p><p><strong>Los objetivos deben ser específicos, medibles, alcanzables, relevantes y con plazos determinados.</strong> Los objetivos vagos producen resultados vagos. Los objetivos SMART producen progreso.</p></div><div class="tip custom-block"><p class="custom-block-title">Regla n.° 3: La regla de la avería</p><p><strong>Los objetivos grandes necesitan hitos trimestrales, mensuales y semanales.</strong> Divida los objetivos grandes en pasos pequeños y viables que pueda completar esta semana.</p></div><div class="tip custom-block"><p class="custom-block-title">Regla n.° 4: La regla de la conexión</p><p><strong>Conecta tus objetivos con tu &quot;por qué&quot; más profundo.</strong> Cuando la motivación se desvanece, tu “por qué” te mantiene en marcha.</p></div><h2 id="conclusion-clave" tabindex="-1">Conclusión clave <a class="header-anchor" href="#conclusion-clave" aria-label="Permalink to &quot;Conclusión clave&quot;">​</a></h2><blockquote><p>Una meta sin un plan es solo un deseo.</p></blockquote><p>Establece metas claras. Desglósalas. Céntrate en lo que controlas. Monitorea tu progreso.</p>',40))])}]]);export{c as __pageData,u as default};
